public VoidVaultState update(ServerLevel world, BlockPos pos, VoidVaultConfig config, VoidVaultServerData serverData, VoidVaultSharedData sharedData) {
        return switch (this) {
            case INACTIVE -> updateActiveState(world, pos, config, serverData, sharedData, config.activationRange());
            case ACTIVE -> updateActiveState(world, pos, config, serverData, sharedData, config.deactivationRange());
            case UNLOCKING -> {
                serverData.setStateUpdatingResumeTime(world.getGameTime() + 20L);
                yield EJECTING;
            }
            case EJECTING -> {
                if (serverData.getItemsToEject().isEmpty()) {
                    serverData.finishEjecting();
                    yield updateActiveState(world, pos, config, serverData, sharedData, config.deactivationRange());
                } else {
                    float f = serverData.getEjectSoundPitchModifier();
                    this.ejectItem(world, pos, serverData.getItemToEject(), f);
                    sharedData.setDisplayItem(serverData.getItemToDisplay());
                    boolean bl = serverData.getItemsToEject().isEmpty();
                    int i = bl ? 20 : 20;
                    serverData.setStateUpdatingResumeTime(world.getGameTime() + i);
                    yield EJECTING;
                }
            }
        };
    }

private void ejectItem(ServerLevel world, BlockPos pos, ItemStack stack, float pitchModifier) {
        DefaultDispenseItemBehavior.spawnItem(world, stack, 2, Direction.UP, Vec3.atBottomCenterOf(pos).relative(Direction.UP, 1.2));
        VoidSpawner.addEjectItemParticles(world, pos, world.getRandom());
        world.playSound(null, pos, ModSounds.VOID_VAULT_EJECT_ITEM.get(), SoundSource.BLOCKS, 1.0F, 0.8F + 0.4F * pitchModifier);
    }

public static void tick(ServerLevel world, BlockPos pos, BlockState state, VoidVaultConfig config, VoidVaultServerData serverData, VoidVaultSharedData sharedData) {
            VoidVaultState vaultState = state.getValue(VoidVaultBlock.STATE);
            if (shouldUpdateDisplayItem(world.getGameTime(), vaultState)) {
                updateDisplayItem(world, vaultState, config, sharedData, pos);
            }

            BlockState blockState = state;
            if (world.getGameTime() >= serverData.getStateUpdatingResumeTime()) {
                blockState = state.setValue(VoidVaultBlock.STATE, vaultState.update(world, pos, config, serverData, sharedData));
                if (!state.equals(blockState)) {
                    changeVaultState(world, pos, state, blockState, config, sharedData);
                }
            }

            if (serverData.dirty || sharedData.dirty) {
                VoidVaultBlockEntity.setChanged(world, pos, state);
                if (sharedData.dirty) {
                    world.sendBlockUpdated(pos, state, blockState, 2);
                }

                serverData.dirty = false;
                sharedData.dirty = false;
            }
        }

public static void tryUnlock(
                ServerLevel world,
                BlockPos pos,
                BlockState state,
                VoidVaultConfig config,
                VoidVaultServerData serverData,
                VoidVaultSharedData sharedData,
                Player player,
                ItemStack stack
        ) {
            VoidVaultState vaultState = state.getValue(VoidVaultBlock.STATE);
            if (canBeUnlocked(config, vaultState)) {
                if (!isValidKey(config, stack)) {
                    playFailedUnlockSound(world, serverData, pos, ModSounds.VOID_VAULT_INSERT_FAIL.get());
                } else if (serverData.hasRewardedPlayer(player)) {
                    playFailedUnlockSound(world, serverData, pos, ModSounds.VOID_VAULT_REJECT.get());
                } else {
                    List<ItemStack> list = generateLoot(world, config, pos, player);
                    if (!list.isEmpty()) {
                        player.awardStat(Stats.ITEM_USED.get(stack.getItem()));
                        if (!player.isCreative()) {
                            stack.shrink(config.keyItem().getCount());
                        }

                        unlock(world, state, pos, config, serverData, sharedData, list);
                        serverData.markPlayerAsRewarded(player);
                        sharedData.updateConnectedPlayers(world, pos, serverData, config, config.deactivationRange());
                    }
                }
            }
        }

private static void unlock(ServerLevel world, BlockState state, BlockPos pos, VoidVaultConfig config, VoidVaultServerData serverData, VoidVaultSharedData sharedData, List<ItemStack> itemsToEject) {
            serverData.setItemsToEject(itemsToEject);
            sharedData.setDisplayItem(serverData.getItemToDisplay());
            serverData.setStateUpdatingResumeTime(world.getGameTime() + 14L);
            changeVaultState(world, pos, state, state.setValue(ModStateProperties.VOID_VAULT_STATE, VoidVaultState.UNLOCKING), config, sharedData);
        }

private static boolean canBeUnlocked(VoidVaultConfig config, VoidVaultState state) {
            return config.lootTable() != LootTable.EMPTY.getLootTableId() && !config.keyItem().isEmpty() && state != VoidVaultState.INACTIVE;
        }

static void changeVaultState(ServerLevel world, BlockPos pos, BlockState oldState, BlockState newState, VoidVaultConfig config, VoidVaultSharedData sharedData) {
            VoidVaultState vaultState = oldState.getValue(VoidVaultBlock.STATE);
            VoidVaultState vaultState2 = newState.getValue(VoidVaultBlock.STATE);
            world.setBlock(pos, newState, Block.UPDATE_ALL);
            vaultState.onStateChange(world, pos, vaultState2, config, sharedData);
        }

public ItemStack getItemToEject() {
        if (this.itemsToEject.isEmpty()) {
            return ItemStack.EMPTY;
        } else {
            this.markDirty();
            return Objects.requireNonNullElse(this.itemsToEject.remove(this.itemsToEject.size() - 1), ItemStack.EMPTY);
        }
    }

public void setItemsToEject(List<ItemStack> itemsToEject) {
        this.itemsToEject.clear();
        this.itemsToEject.addAll(itemsToEject);
        this.totalEjectionsNeeded = this.itemsToEject.size();
        this.markDirty();
    }

@VisibleForTesting
    public void markPlayerAsRewarded(Player player) {
        this.rewardedPlayers.add(player.getUUID());
        if (this.rewardedPlayers.size() > 128) {
            Iterator<UUID> iterator = this.rewardedPlayers.iterator();
            if (iterator.hasNext()) {
                iterator.next();
                iterator.remove();
            }
        }

        this.markDirty();
    }

public void finishEjecting() {
        this.totalEjectionsNeeded = 0;
        this.markDirty();
    }

public void setStateUpdatingResumeTime(long stateUpdatingResumesAt) {
        this.stateUpdatingResumesAt = stateUpdatingResumesAt;
        this.markDirty();
    }

private void tickOrbiting() {
        // But we might want it to follow the owner if not fired yet.
        if (this.dracula == null && this.draculaUUID != null && this.level() instanceof ServerLevel serverLevel) {
            Entity entity = serverLevel.getEntity(this.draculaUUID);
            if (entity instanceof Dracula d) {
                this.dracula = d;
            }
        }

        // orbit Dracula
        if (this.dracula != null && this.dracula.isAlive()) {
            double angle = (this.level().getGameTime() * 0.1) + (this.indexOffset * (Math.PI * 2 / this.maxCount));
            double x = this.dracula.getX() + Math.cos(angle) * 1.5;
            double z = this.dracula.getZ() + Math.sin(angle) * 1.5;
            double y = this.dracula.getY() + 1.5 + Math.sin(this.level().getGameTime() * 0.05 + this.indexOffset) * 0.5;

            this.setPos(x, y, z);
            this.setYRot((float) (angle * (180 / Math.PI)));
            this.yRotO = this.getYRot();
            this.xRotO = this.getXRot();
        } else if (!this.level().isClientSide()) {
            this.discard();
        }
    }

@Override
    public void tick() {
        super.tick();
        if (this.isFlying()) {
            tickFlying();
        } else {
            tickOrbiting();
        }
    }

private void tickFlying() {
        this.lifeTicks++;
        if (this.lifeTicks > MAX_LIFE) {
            this.discard();
            return;
        }

        Vec3 movement = this.getDeltaMovement();
        Vec3 nextPos = this.position().add(movement);

        EntityHitResult entityHitResult = ProjectileUtil.getEntityHitResult(this.level(), this, this.position(), nextPos, this.getBoundingBox().expandTowards(movement).inflate(1.0D), this::canHitEntity);
        if (entityHitResult != null) {
            onHit(entityHitResult);
        }

        this.setPos(nextPos);
        if (movement.lengthSqr() > 1.0E-7D) {
            this.setYRot((float) (Math.atan2(-movement.x, movement.z) * (180 / Math.PI)));
            this.setXRot((float) (-Math.asin(movement.y / movement.length()) * (180 / Math.PI)));
        }
    }

public void shoot(LivingEntity target) {
        this.setFlying(true);
        Vec3 direction = target.getHitbox().getCenter().subtract(this.position()).normalize();
        this.setDeltaMovement(direction.scale(3));
        this.setYRot((float) (Math.atan2(-direction.x, direction.z) * (180 / Math.PI)));
        this.setXRot((float) (-Math.asin(direction.y) * (180 / Math.PI)));
        this.yRotO = this.getYRot();
        this.xRotO = this.getXRot();
    }

@Override
    protected void onHitEntity(EntityHitResult pResult) {
        super.onHitEntity(pResult);
        Entity entity = pResult.getEntity();
        if (entity instanceof LivingEntity living && !this.level().isClientSide()) {
            if (living != this.getOwner()) {
                if (this.level() instanceof ServerLevel serverLevel) {
                    DamageHandler.hurtModded(serverLevel, living, damageSources -> damageSources.flyingNeedle((LivingEntity) this.getOwner()), damage);
                    this.discard();
                }
            }
        }
    }

@Override
    protected boolean canHitEntity(Entity pTarget) {
        return super.canHitEntity(pTarget) && pTarget != this.getOwner() && this.isFlying();
    }

@Override
    protected void readAdditionalSaveData(ValueInput input) {
        super.readAdditionalSaveData(input);
        this.lifeTicks = input.getIntOr("life_ticks", 0);
        this.damage = input.getFloatOr("damage", 4.0f);
        this.indexOffset = input.getIntOr("index_offset", 0);
        this.draculaUUID = input.read("dracula_uuid", UUIDUtil.CODEC).orElse(null);
        this.setFlying(input.getBooleanOr("flying", false));
    }

@Override
    protected void addAdditionalSaveData(ValueOutput output) {
        super.addAdditionalSaveData(output);
        output.putInt("life_ticks", this.lifeTicks);
        output.putFloat("damage", this.damage);
        output.putInt("index_offset", this.indexOffset);
        if (this.draculaUUID != null) {
            output.store("dracula_uuid", UUIDUtil.CODEC, this.draculaUUID);
        }
        output.putBoolean("flying", this.isFlying());
    }

@Override
    public void update() {
        super.update();

        this.currentChangeTicks++;
        if (!this.entity.swinging) {
            this.entity.swing(InteractionHand.MAIN_HAND);
        }

        if (this.entity.level().getGameTime() % 2 == 0) {
            ((ServerLevel) this.entity.level())
                    .sendParticles(ParticleTypes.PORTAL, this.entity.getX(),
                            this.entity.getY() + 0.5, this.entity.getZ(), 3,
                            0.5, 0.0, 0.0,
                            0.0);
        }

        if (this.isEnabled())
            this.updateTime();

        if (this.currentChangeTicks == this.requiredChangeTicks.get()) {
            this.finishChangeTime();
        }
    }

@Override
    public void onInit() {
        this.newTime = this.getNewTime();

        if (!this.isEnabled()) {
            if (this.entity.getOwner() instanceof Player player)
                player.sendSystemMessage(this.getDisabledMessage());
            this.finishChangeTime();
        }
    }

public void updateTime() {
        var server = this.entity.level().getServer();
        var clockHolder = server.registryAccess().lookupOrThrow(Registries.WORLD_CLOCK).getOrThrow(WorldClocks.OVERWORLD);
        var clockManager = server.clockManager();
        var currentTime = clockManager.getTotalTicks(clockHolder);

        var remainingTime = this.newTime - currentTime;
        var remainingTicks = Math.max(this.requiredChangeTicks.get() - this.currentChangeTicks, 1);
        var timeChange = remainingTime / remainingTicks;

        var interpolatedTime = currentTime + timeChange;

        if (interpolatedTime >= this.newTime) {
            interpolatedTime = this.newTime;
        }

        clockManager.setTotalTicks(clockHolder, interpolatedTime);
    }

public void finishChangeTime() {
        this.entity.level().playSound(null, this.entity.blockPosition(), SoundEvents.BEACON_ACTIVATE, SoundSource.NEUTRAL, 1, 1);
        this.entity.die(this.entity.damageSources().fellOutOfWorld());
        this.entity.remove(RemovalReason.DISCARDED);
    }

@Override
    public CompoundTag writeJobToNBT(CompoundTag compound, Provider provider) {
        compound.putInt("currentChangeTicks", this.currentChangeTicks);
        compound.putInt("requiredChangeTicks", this.requiredChangeTicks.get());
        compound.putLong("newTime", this.newTime);
        return super.writeJobToNBT(compound, provider);
    }

@Override
    public void readJobFromNBT(CompoundTag compound, Provider provider) {
        super.readJobFromNBT(compound, provider);
        this.currentChangeTicks = compound.getIntOr("currentChangeTicks", 0);
        var requiredChangeTicks = compound.getIntOr("requiredChangeTicks", 0);
        this.requiredChangeTicks = () -> requiredChangeTicks;
        this.newTime = compound.getLongOr("newTime", 0L);
    }

@SubscribeEvent
	public static void hauntedBellCreatesPulse(PlayerTickEvent.Post event) {
		Player player = event.getEntity();

		if (player.level().isClientSide())
			return;

		if (player.isSpectator())
			return;
		if (!player.isHolding(AllBlocks.HAUNTED_BELL::isIn))
			return;

		boolean firstPulse = false;

		try {
			IntAttached<Entity> ticker = WARMUP.get(player.getUUID(), () -> IntAttached.with(WARMUP_TICKS, player));
			firstPulse = ticker.getFirst() == 1;
			ticker.decrement();
			if (!ticker.isOrBelowZero())
				return;
		} catch (ExecutionException ignored) {}

		long gameTime = player.level().getGameTime();
		if ((firstPulse || gameTime % RECHARGE_TICKS != 0) && player.level() instanceof ServerLevel serverLevel)
			sendPulse(serverLevel, player.blockPosition(), DISTANCE, false);
	}

public static void sendPulse(ServerLevel world, BlockPos pos, int distance, boolean canOverlap) {
		ChunkPos chunk = world.getChunkAt(pos).getPos();
		CatnipServices.NETWORK.sendToClientsTrackingChunk(world, chunk, new SoulPulseEffectPacket(pos, distance, canOverlap));
	}

@Override
    public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
        double potency = spellStat.getPotency();
        if (WandUtil.enchantedFocus(caster)){
            potency += WandUtil.getPotencyLevel(caster) / 2.0D;
        }
        if (this.victim != null){
            try {
                Vec3 vec3 = this.victim.getDeltaMovement();
                Vec3 force = (caster.getLookAngle()
                        .normalize()
                        .scale(Math.max(caster.distanceTo(this.victim), 4))
                        .add(caster.position())
                        .subtract(this.victim.position()))
                        .scale(potency);
                if (force.y > 0) {
                    this.victim.resetFallDistance();
                }
                Vec3 newMotion = force.subtract(vec3).scale(0.25).add(vec3);
                Vec3 delta = newMotion.subtract(vec3);
                Vec3 clampedMotion = new Vec3(signedMin(delta.x, force.x * 4), signedMin(delta.y, force.y * 4), signedMin(delta.z, force.z * 4));
                MobUtil.push(this.victim, clampedMotion, 0.25D);
                Vec3 old = new Vec3(this.victim.xOld, this.victim.yOld, this.victim.zOld);
                Vec3 travel = this.victim.position().subtract(old);
                if (this.victim.horizontalCollision && this.victim instanceof LivingEntity livingTarget) {
                    double d11 = livingTarget.getDeltaMovement().horizontalDistance();
                    float f1 = (float) (d11 * 10.0D - 3.0D);
                    int airborne = (int) travel.horizontalDistanceSqr() / 2;
                    if (f1 >= 1.0F) {
                        if (livingTarget.hurt(livingTarget.damageSources().flyIntoWall(), 4.0F + (airborne + 1) * 0.5F)) {
                            livingTarget.playSound(livingTarget.getFallSounds().big(), 2.0F, 1.0F);
                        }
                    }
                }
                if (CuriosFinder.hasCurio(caster, ModItems.RING_OF_FORCE.get())){
                    this.victim.setAirSupply(Math.max(-20, this.victim.getAirSupply() - 10));
                    if (this.victim.getAirSupply() <= -20){
                        this.victim.setAirSupply(0);
                        this.victim.hurt(ModDamageSource.choke(caster, caster), 2.0F);
                    }
                }
                ServerParticleUtil.addParticlesAroundMiddleSelf(worldIn, ParticleTypes.PORTAL, this.victim);
            } catch (NullPointerException exception) {
                caster.stopUsingItem();
            }
        } else {
            this.findVictim(worldIn, caster, spellStat);
        }
    }

@Override
    public boolean conditionsMet(ServerLevel worldIn, LivingEntity caster, SpellStat spellStat) {
        if (caster.hurtTime > 0){
            return false;
        }
        if (this.victim != null) {
            int range = spellStat.getRange();
            if (WandUtil.enchantedFocus(caster)){
                range += WandUtil.getRangeLevel(caster);
            }
            if (this.victim.distanceTo(caster) > range) {
                this.victim = null;
                return false;
            }
        }
        return true;
    }

@Override
    public void startSpell(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
        super.startSpell(worldIn, caster, staff, spellStat);
        this.victim = null;
        this.findVictim(worldIn, caster, spellStat);
    }

@Override
    public void stopSpell(ServerLevel worldIn, LivingEntity caster, ItemStack staff, ItemStack focus, int castTime, SpellStat spellStat) {
        this.victim = null;
        if (caster instanceof Player player){
            SEHelper.addSpellCooldown(player, this, MathHelper.secondsToTicks(5));
            SEHelper.sendSEUpdatePacket(player);
        }
        super.stopSpell(worldIn, caster, staff, focus, castTime, spellStat);
    }

public void findVictim(ServerLevel worldIn, LivingEntity caster, SpellStat spellStat) {
        double potency = spellStat.getPotency();
        int range = spellStat.getRange();
        if (WandUtil.enchantedFocus(caster)){
            potency += WandUtil.getPotencyLevel(caster) / 2.0D;
            range += WandUtil.getRangeLevel(caster);
        }
        Entity target = MobUtil.getSingleTarget(worldIn, caster, range, 3,
                entity -> EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(entity)
                        && !entity.getType().is(ModTags.EntityTypes.TELEKINESIS_IMMUNE)
                        && !MobUtil.hasEntityTypesConfig(SpellConfig.TelekinesisBlackList.get(), entity.getType())
                        && !(entity instanceof AbstractHurtingProjectile));
        if (caster instanceof Mob mob) {
            target = mob.getTarget();
        }
        if (target != null) {
            boolean flag = true;
            if ((caster.getBoundingBox().inflate(0.5D).getSize() * potency) >= target.getBoundingBox().getSize()) {
                if (this.victim instanceof LivingEntity livingTarget){
                    if (livingTarget.getMaxHealth() >= SpellConfig.TelekinesisMaxHealth.get()){
                        flag = false;
                    }
                }
            }
            if (flag) {
                this.victim = target;
            }
        }
    }

